class Solution {
  public int maxRemoval(int[] nums, int[][] queries) {
    int n = nums.length;
    List<List<Integer>> startingAt = new ArrayList<>();
    for (int i = 0; i < n; i++) startingAt.add(new ArrayList<>());
    for (int[] q : queries) startingAt.get(q[0]).add(q[1]);
    PriorityQueue<Integer> ends =
        new PriorityQueue<>(Collections.reverseOrder()); // available queries by right end
    int[] expire = new int[n + 1];
    int active = 0, used = 0;
    for (int i = 0; i < n; i++) {
      active -= expire[i];
      ends.addAll(startingAt.get(i));
      while (active < nums[i]) {
        // greedily spend the available query that reaches furthest
        if (ends.isEmpty() || ends.peek() < i) return -1;
        int end = ends.poll();
        active++;
        used++;
        expire[end + 1]++;
      }
    }
    return queries.length - used;
  }
}
